            "/invoices", "/payments", "/reports/dashboard", "/export/csv"
        ]
    })


@app.post("/families")
def create_family():
    data = request.get_json(force=True)
    fid = data["id"]
    family = Family(
        id=fid,
        name=data["name"],
        address=data.get("address", ""),
        email=data.get("email", ""),
        phone=data.get("phone", ""),
        contacts=data.get("contacts", []),
    )
    state["families"][fid] = family
    log("family.create", data.get("actor", "system"), serialize(family))
    return jsonify(serialize(family)), 201


@app.get("/families")
def list_families():
    return jsonify([serialize(f) for f in state["families"].values()])


@app.post("/children")
def create_child():
