        return jsonify({"error": "Unknown child"}), 404
    classroom_id = data["classroom_id"]
    room = state["classrooms"].get(classroom_id)
    if not room:
        return jsonify({"error": "Unknown classroom"}), 404
    enrolled = sum(1 for c in state["children"].values() if c.classroom_id == room.id)
    override = bool(data.get("override", False))
    if enrolled >= room.capacity and not override:
        child.waiting_list = True
        if cid not in state["waiting_list"]:
            state["waiting_list"].append(cid)
        return jsonify({"error": "Classroom full", "waiting_list": True}), 409
    child.classroom_id = classroom_id
    child.waiting_list = False
    if cid in state["waiting_list"]:
        state["waiting_list"].remove(cid)
    log("child.assign", data.get("actor", "system"), {"child_id": cid, "classroom_id": classroom_id, "override": override})
    return jsonify(serialize(child))


@app.post("/children/<cid>/immunization")
def update_immunization(cid):
    data = request.get_json(force=True)
    child = state["children"].get(cid)
    if not child:
        return jsonify({"error": "Unknown child"}), 404
    child.immunization_status = data.get("status", child.immunization_status)
    child.immunization_due = data.get("due", child.immunization_due)
    child.compliance_verified = bool(data.get("verified", False))
