    log("attendance.checkin", entry["actor"], {"child_id": child.id})
    return jsonify(entry), 201


@app.post("/attendance/checkout")
def checkout():
    data = request.get_json(force=True)
    child = state["children"].get(data["child_id"])
    if not child:
        return jsonify({"error": "Unknown child"}), 404
    entry = {"type": "out", "at": now_iso(), "actor": data.get("actor", "system")}
    child.attendance.append(entry)
    log("attendance.checkout", entry["actor"], {"child_id": child.id})
    return jsonify(entry), 201


@app.get("/attendance/review")
def attendance_review():
    return jsonify({cid: c.attendance for cid, c in state["children"].items()})


@app.post("/invoices")
def create_invoice():
