    invoice = Invoice(
        id=data["id"],
        family_id=data["family_id"],
        child_id=data.get("child_id"),
        amount=float(data["amount"]),
        balance=float(data.get("balance", data["amount"])),
    )
    state["invoices"][invoice.id] = invoice
    log("invoice.create", data.get("actor", "system"), serialize(invoice))
    return jsonify(serialize(invoice)), 201


@app.post("/invoices/<iid>/adjustments")
def add_adjustment(iid):
    data = request.get_json(force=True)
    invoice = state["invoices"].get(iid)
    if not invoice:
        return jsonify({"error": "Unknown invoice"}), 404
    adjustment = {"reason": data["reason"], "amount": float(data["amount"]), "type": data.get("type", "adjustment"), "at": now_iso(), "actor": data.get("actor", "system")}
    invoice.adjustments.append(adjustment)
    invoice.balance += adjustment["amount"]
    invoice.status = "open" if invoice.balance > 0 else "paid"
    log("invoice.adjustment", adjustment["actor"], {"invoice_id": iid, **adjustment})
    return jsonify(serialize(invoice))


@app.post("/payments")
def take_payment():
    data = request.get_json(force=True)
    invoice = state["invoices"].get(data["invoice_id"])
    if not invoice:
        return jsonify({"error": "Unknown invoice"}), 404
    amount = float(data["amount"])
    payment = {"amount": amount, "method": data.get("method", "card"), "payer": data.get("payer", "authorized"), "at": now_iso(), "status": "success"}
    invoice.payments.append(payment)
    invoice.balance = round(invoice.balance - amount, 2)
    if invoice.balance <= 0:
        invoice.status = "paid"
        invoice.balance = 0.0
    else:
        invoice.status = "partial"
    log("payment.record", data.get("actor", "system"), {"invoice_id": invoice.id, **payment})
    return jsonify(serialize(invoice))


@app.get("/reports/dashboard")
def dashboard():
    return jsonify({
