    })


@app.get("/export/csv")
def export_csv():
    kind = request.args.get("kind", "families")
    output = io.StringIO()
    writer = csv.writer(output)
    if kind == "families":
        writer.writerow(["id", "name", "email", "phone"])
        for f in state["families"].values():
            writer.writerow([f.id, f.name, f.email, f.phone])
    elif kind == "children":
        writer.writerow(["id", "family_id", "name", "site", "classroom_id", "immunization_status", "status"])
        for c in state["children"].values():
            writer.writerow([c.id, c.family_id, c.name, c.site, c.classroom_id or "", c.immunization_status, child_status(c)])
    else:
        return jsonify({"error": "Unsupported export kind"}), 400
    return Response(output.getvalue(), mimetype="text/csv")


@app.post("/imports/csv")
def import_csv():
    kind = request.args.get("kind", "families")
    content = request.data.decode("utf-8")
    reader = csv.DictReader(io.StringIO(content))
    imported = []
    errors = []
    for idx, row in enumerate(reader, start=2):
        try:
            if kind == "families":
                if not row.get("id") or not row.get("name"):
                    raise ValueError("missing id or name")
                state["families"][row["id"]] = Family(id=row["id"], name=row["name"], email=row.get("email", ""), phone=row.get("phone", ""))
                imported.append(row["id"])
            elif kind == "children":
                if row.get("family_id") not in state["families"]:
                    raise ValueError("unknown family_id")
                state["children"][row["id"]] = Child(id=row["id"], family_id=row["family_id"], name=row["name"], dob=row.get("dob", ""), site=row.get("site", ""))
                imported.append(row["id"])
            else:
                raise ValueError("unsupported kind")
        except Exception as exc:
            errors.append({"row": idx, "error": str(exc)})
    return jsonify({"imported": imported, "errors": errors})


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000, debug=False)
