        self.client.post("/families", json={"id": "f1", "name": "Smith"})
        self.client.post("/children", json={"id": "c1", "family_id": "f1", "name": "Ava", "dob": "2020-01-01", "site": "north"})
        self.client.post("/classrooms", json={"id": "r1", "site": "north", "name": "Toddlers", "capacity": 1})
        resp = self.client.post("/children/c1/assign", json={"classroom_id": "r1"})
        self.assertEqual(resp.status_code, 200)
        dash = self.client.get("/reports/dashboard").get_json()
        self.assertEqual(dash["children"], 1)

    def test_waiting_list_when_full(self):
        self.client.post("/families", json={"id": "f1", "name": "Smith"})
        self.client.post("/families", json={"id": "f2", "name": "Jones"})
        self.client.post("/children", json={"id": "c1", "family_id": "f1", "name": "Ava", "dob": "2020-01-01", "site": "north"})
        self.client.post("/children", json={"id": "c2", "family_id": "f2", "name": "Ben", "dob": "2020-01-02", "site": "north"})
        self.client.post("/classrooms", json={"id": "r1", "site": "north", "name": "Toddlers", "capacity": 1})
        self.client.post("/children/c1/assign", json={"classroom_id": "r1"})
        resp = self.client.post("/children/c2/assign", json={"classroom_id": "r1"})
        self.assertEqual(resp.status_code, 409)
        self.assertIn("c2", app.state["waiting_list"])

    def test_partial_payment(self):
        self.client.post("/families", json={"id": "f1", "name": "Smith"})
        self.client.post("/invoices", json={"id": "i1", "family_id": "f1", "amount": 100, "balance": 100})
        resp = self.client.post("/payments", json={"invoice_id": "i1", "amount": 25, "method": "card"})
        data = resp.get_json()
        self.assertEqual(data["balance"], 75.0)
        self.assertEqual(data["status"], "partial")

    def test_csv_import_validation(self):
        body = "id,name,email,phone\nf1,Smith,smith@example.com,123\n,NoId,,\n"
        resp = self.client.post("/imports/csv?kind=families", data=body)
        data = resp.get_json()
        self.assertIn("f1", data["imported"])
        self.assertEqual(len(data["errors"]), 1)

if __name__ == "__main__":
    unittest.main()
